from prometheus_client import REGISTRY

@router.get("/metrics/sla/{tenant_id}")
async def get_tenant_sla_metrics(
    tenant_id: str,
    current_user: User = Depends(get_current_user)
):
    if tenant_id != current_user.tenant_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to tenant SLA telemetry")

    matching_samples = []
    for metric in REGISTRY.collect():
        for sample in metric.samples:
            if sample.labels.get("tenant_id") == tenant_id:
                matching_samples.append({
                    "name": sample.name,
                    "labels": sample.labels,
                    "value": sample.value,
                    "timestamp": sample.timestamp
                })
    return {"tenant_id": tenant_id, "samples": matching_samples}
